export const PLAYING_CARDS: PlayingCardDef[] = [
  // ── HEARTS ──
  { id: 1, rank: "A", suit: "hearts", name: "Ace of Hearts", glyph: "🂱", element: "Water", keywords: ["new love", "emotional beginning", "heartfelt offer", "home", "joy", "passion"], meaning: "The Ace of Hearts is the seed of love and emotional fulfillment. It represents a new beginning in matters of the heart — a new relationship, a deepening of existing love, or a profound emotional awakening. This is the card of pure potential in love, carrying the energy of openness, vulnerability, and the courage to feel deeply. When this card appears, the heart opens and love flows freely. It can indicate the start of a romantic relationship, a reconciliation with a loved one, or simply a moment of profound self-love and acceptance. In practical terms, it often precedes a proposal, a declaration of feelings, or the birth of a child. The Ace of Hearts is one of the most positive cards in the deck, carrying the promise that love is not only possible but imminent. Paired with the Ace of Diamonds, it suggests a love that brings material security. Paired with the Ace of Spades, it warns that truth may hurt before it heals. The energy is fresh, innocent, and full of hope.", reversedMeaning: "The Ace of Hearts reversed suggests blocked emotions, fear of vulnerability, or a love that cannot be expressed. You may be holding back your feelings, or someone else may be unable to return your affection. It can indicate a missed romantic opportunity, a love that was never quite born, or emotional numbness. The heart is willing but circumstances are not cooperating. This card reversed asks you to examine what fear is preventing you from opening up.", color: "red" },
  { id: 2, rank: "2", suit: "hearts", name: "Two of Hearts", glyph: "🂲", element: "Water", keywords: ["partnership", "attraction", "mutual affection", "connection", "unity"], meaning: "The Two of Hearts represents partnership, mutual attraction, and the merging of two souls. It speaks to the chemistry between people — not just romantic partners, but close friends, family bonds, and even business partnerships built on genuine affection. This card suggests a connection that is balanced and reciprocal. Each person gives and receives in equal measure. The Two of Hearts is the card of the handshake, the hug, the first date, the reuniting of old friends. It can indicate a new relationship in its early stages or a current relationship entering a phase of deeper harmony. The energy is warm, optimistic, and collaborative.", reversedMeaning: "The Two of Hearts reversed indicates imbalance in a relationship, unrequited feelings, or a partnership that is out of sync. One person is giving more than the other. There may be a lack of communication, mismatched expectations, or a connection that is fading. This card reversed can also indicate a breakup or separation where both parties still care but cannot make it work. The harmony is disrupted; the balance needs to be restored or released.", color: "red" },
  { id: 3, rank: "3", suit: "hearts", name: "Three of Hearts", glyph: "🂳", element: "Water", keywords: ["celebration", "community", "friendship", "joy", "social gathering"], meaning: "The Three of Hearts is the card of celebration, friendship, and social joy. It represents gatherings with loved ones, parties, shared meals, and the simple pleasure of being among people who care about you. This is a card of emotional abundance — not the intensity of romantic love (that is the Ace), but the steady warmth of community and belonging. It can indicate a wedding, a reunion, a holiday gathering, or any occasion where hearts come together in joy. The Three of Hearts reminds us that we are not meant to be alone; happiness multiplies when shared.", reversedMeaning: "The Three of Hearts reversed suggests social isolation, strained friendships, or a celebration that falls flat. You may feel left out, or a group you were part of has dissolved. It can indicate gossip, social anxiety, or a party or event that brings more stress than joy. The community you relied on may not be available when you need them. This card reversed asks you to examine your social connections and whether they truly nourish you.", color: "red" },
  { id: 4, rank: "4", suit: "hearts", name: "Four of Hearts", glyph: "🂴", element: "Water", keywords: ["stability", "domestic peace", "contentment", "home", "security"], meaning: "The Four of Hearts represents emotional stability, domestic peace, and the security of a loving home. This is the card of the happy household — a place where you are safe, loved, and accepted exactly as you are. It speaks to the quiet contentment that comes not from excitement or passion, but from knowing you belong. In relationships, it indicates a solid foundation built on trust and mutual respect. In family matters, it suggests harmony among relatives and a home that nourishes all who enter. The Four of Hearts is a card of gratitude for the simple comforts: a warm bed, a shared meal, a familiar voice.", reversedMeaning: "The Four of Hearts reversed indicates domestic unrest, instability in the home, or emotional insecurity. There may be arguments at home, a lack of peace in your living situation, or a relationship that feels more like a battleground than a sanctuary. It can also indicate a home that feels empty or lonely even when others are present — the house is not a home. This card reversed asks you to address what is making your emotional foundation feel shaky.", color: "red" },
  { id: 5, rank: "5", suit: "hearts", name: "Five of Hearts", glyph: "🂵", element: "Water", keywords: ["change", "emotional challenge", "loss", "letting go", "adaptation"], meaning: "The Five of Hearts represents change and emotional challenge within relationships. It is the card of the difficult conversation, the tearful goodbye, the shift that must happen even though it hurts. Unlike the violent severing of the Spades suit, the Five of Hearts brings change that comes with sadness but not destruction. A relationship may be changing form — from romantic to platonic, from close to distant, from present to memory. The pain is real, but the heart survives. This card often appears when a relationship has run its natural course and both parties must accept that what was cannot continue. The Five of Hearts asks you to grieve what is lost while trusting that your heart can hold both love and loss.", reversedMeaning: "The Five of Hearts reversed suggests resistance to necessary change in a relationship. You may be clinging to something that is already over, or refusing to acknowledge that a connection has shifted. The reversed position can also indicate that the worst of the emotional difficulty has passed and you are entering a phase of healing. The pain is still present but no longer overwhelming. This card reversed asks what you need to release so that your heart can begin to heal.", color: "red" },
  { id: 6, rank: "6", suit: "hearts", name: "Six of Hearts", glyph: "🂶", element: "Water", keywords: ["nostalgia", "past", "childhood", "memories", "reunion"], meaning: "The Six of Hearts is the card of nostalgia, childhood memories, and the past reaching into the present. It represents old friends who still matter, family traditions, first loves, and the people who shaped who you are. When this card appears, someone from your past may re-enter your life, or you may find yourself revisiting a place, a memory, or a feeling that you thought was behind you. The Six of Hearts is not about living in the past but about honoring the roots that made you. It often precedes reunions — with a childhood friend, an old lover, a family member from whom you have been estranged. The energy is gentle, sweet, and healing. This card assures you that the people who mattered still matter, and that love, once real, never truly disappears.", reversedMeaning: "The Six of Hearts reversed indicates being stuck in the past, unable to move forward from an old relationship or childhood wound. You may be idealizing what was, comparing everyone to someone who is gone, or refusing to heal old heartbreaks. The reverse warns against letting nostalgia become a prison. The past should inform you, not trap you. It can also indicate that a hoped-for reunion will not happen, or that returning to a past situation would be a mistake.", color: "red" },
  { id: 7, rank: "7", suit: "hearts", name: "Seven of Hearts", glyph: "🂷", element: "Water", keywords: ["dreams", "illusions", "choices", "discernment", "fantasy"], meaning: "The Seven of Hearts represents dreams, illusions, and the choices that come when fantasy meets reality. This is the card of the romantic idealist, the dreamer who sees what could be rather than what is. It warns against wishful thinking in matters of the heart. You may be seeing what you want to see rather than what is really there. Is this love, or is it projection? Is this connection real, or are you falling in love with potential? The Seven of Hearts asks you to look honestly at your relationships and separate truth from fantasy. It is not a negative card — dreams have value — but it insists that you ground those dreams in reality. If you are facing a choice between two lovers or two paths, this card counsels patience and clear-sighted discernment.", reversedMeaning: "The Seven of Hearts reversed indicates a moment of clarity: the illusions are falling away and you see the truth of a situation. This may be painful — discovering that someone was not who you thought, or that a relationship was built on fantasy — but it is necessary. The reverse brings the gift of clear perception. You can now make decisions based on reality rather than hope. While it may sting, this card reversed ultimately frees you from self-deception.", color: "red" },
  { id: 8, rank: "8", suit: "hearts", name: "Eight of Hearts", glyph: "🂸", element: "Water", keywords: ["moving on", "letting go", "departure", "new direction", "release"], meaning: "The Eight of Hearts represents the decision to move on emotionally. This is the card of leaving a relationship or situation that no longer fulfills you, even if it is not actively harmful. The Eight of Hearts is not forced out — you choose to leave because you know, deep in your heart, that there is something more for you. This is one of the most courageous cards in the deck: the willingness to walk away from comfort in search of genuine fulfillment. It often appears when someone is ending a relationship that is \"fine\" but not nourishing, leaving a job that is stable but soulless, or moving to a new place where they know no one. The departure may be painful, but the Eight of Hearts promises that the unknown is better than the unfulfilling familiar.", reversedMeaning: "The Eight of Hearts reversed indicates fear of moving on, staying in a situation that has become empty. You know you should leave but cannot bring yourself to do it. Comfort, fear of being alone, or guilt keeps you in place. This card reversed can also indicate that someone has left you and you are struggling to accept it. The heart has already gone, even if your body has not. The reverse asks you to honestly assess what you are afraid of losing and whether it is worth staying for.", color: "red" },
  { id: 9, rank: "9", suit: "hearts", name: "Nine of Hearts", glyph: "🂹", element: "Water", keywords: ["wish fulfilled", "contentment", "dreams come true", "happiness", "fulfillment"], meaning: "The Nine of Hearts is the wish card. It represents emotional fulfillment, the realization of your heart's desire, and profound contentment. When this card appears, a deeply held wish is about to come true. This is not a superficial desire but something you have truly longed for — perhaps in silence, perhaps for years. The Nine of Hearts is the card of the happy ending, the answered prayer, the phone call you have been waiting for. It brings emotional satisfaction in relationships, family, or creative expression. In readings, it is one of the most positive cards possible. Whatever you have been hoping for in matters of the heart is closer than you think. The Nine of Hearts assures you that your emotional investment has not been in vain; the harvest is coming.", reversedMeaning: "The Nine of Hearts reversed indicates a wish delayed or a dream that has not yet materialized. You may feel disappointed or question whether what you want will ever arrive. The reversed position cautions against impatience — the wish may still come true, but not on your timeline. It can also indicate that what you thought you wanted would not bring the happiness you expect. This card reversed asks you to examine whether your wish is truly your own or something you think you should want.", color: "red" },
  { id: 10, rank: "10", suit: "hearts", name: "Ten of Hearts", glyph: "🂺", element: "Water", keywords: ["family bliss", "lasting love", "legacy", "harmony", "completion"], meaning: "The Ten of Hearts represents the ultimate fulfillment of the heart's journey: lasting love, family happiness, and emotional legacy. This is the card of the happy family, the lifelong marriage, the home filled with love and children and tradition. It speaks to what you build that will outlast you — not in material terms but in love that passes from generation to generation. The Ten of Hearts indicates a relationship or family situation that is whole, complete, and deeply satisfying. It can represent a marriage, a commitment ceremony, a family reunion, or simply the quiet joy of knowing you are surrounded by people who love you unconditionally. In career readings, it suggests work that aligns with your heart's values. This is one of the most fortunate cards in the deck, promising that love, in its deepest and most lasting form, is yours.", reversedMeaning: "The Ten of Hearts reversed indicates dysfunction in the family, a broken home, or a relationship that has failed to reach its potential. There may be unresolved conflict among family members, a divorce or separation that has left scars, or a sense that your emotional life is fragmented. It can also indicate a family secret that is causing harm, or a legacy of emotional pain passed down through generations. This card reversed asks you to examine what patterns in your family history need healing. The completion is disrupted; the heart's journey is not yet over.", color: "red" },
  { id: 11, rank: "J", suit: "hearts", name: "Jack of Hearts", glyph: "🂻", element: "Water", keywords: ["young lover", "messenger of love", "romantic news", "youthful passion", "admirer"], meaning: "The Jack of Hearts represents a young lover, a romantic message, or the passionate energy of new love. This is the card of the crush, the love letter, the unexpected compliment that makes your heart skip. The Jack of Hearts is youthful, sincere, and emotionally open. It can represent a person — usually younger, fair-haired, or emotionally expressive — who brings romantic news or a declaration of affection. It can also represent the part of yourself that is still innocent in love, still willing to take risks for connection. In a reading, this card often precedes a confession of feelings, a first date, or a romantic gesture. The energy is sweet, hopeful, and unguarded.", reversedMeaning: "The Jack of Hearts reversed indicates a false lover, emotional immaturity, or insincere romantic gestures. Someone may be playing with your affections, or a young person in your life is not ready for the emotional weight of a relationship. It can also indicate a message of love that is not delivered or is misinterpreted. The reverse warns against naivety in romantic matters — not everyone who expresses interest is genuine.", color: "red" },
  { id: 12, rank: "Q", suit: "hearts", name: "Queen of Hearts", glyph: "🂽", element: "Water", keywords: ["nurturing woman", "emotional wisdom", "compassion", "motherly love", "intuition"], meaning: "The Queen of Hearts represents the mature feminine principle in matters of love: nurturing, intuitive, emotionally wise, and deeply compassionate. This is the card of the mother, the healer, the therapist, the woman who leads with her heart. The Queen of Hearts has seen love in all its forms — joy, loss, longing, fulfillment — and has learned from every experience. She does not judge; she understands. When this card appears, it may represent a specific person (usually a woman with light hair or a warm, maternal energy) or the querent's own capacity for emotional wisdom. The Queen of Hearts counsels leading with love, trusting your intuition, and creating a space where others feel safe to be vulnerable. She is the heart of the home, the keeper of emotional bonds, and the witness whose love heals simply by being present.", reversedMeaning: "The Queen of Hearts reversed indicates emotional dependency, smothering love, or a woman who uses her emotional intelligence to manipulate. She may be overly attached, unable to let her children or partner grow independently. The reversed Queen can also represent someone who has closed her heart due to past wounds — a woman who was once nurturing but has become bitter or cold. In a reading, this card reversed asks whether your emotional expressions are truly loving or whether they come from fear of being alone.", color: "red" },
  { id: 13, rank: "K", suit: "hearts", name: "King of Hearts", glyph: "🂾", element: "Water", keywords: ["benevolent leader", "emotional strength", "kindness", "generosity", "warm authority"], meaning: "The King of Hearts represents a man who leads with his heart — emotionally mature, kind, generous, and secure enough to be vulnerable. This is the card of the loving husband, the devoted father, the therapist, the mentor whose wisdom comes from emotional experience. The King of Hearts has integrated his emotions with his authority; he is powerful precisely because he is not afraid to feel. He is generous with his affection and protective of those he loves. When this card appears, it may represent a specific person (usually an older man with light hair or a warm demeanor) or the querent's own capacity for benevolent emotional leadership. The King of Hearts counsels that true strength includes the ability to love openly and to lead with compassion.", reversedMeaning: "The King of Hearts reversed indicates a man who is emotionally manipulative, possessive, or unable to express his feelings. He may be domineering in relationships, using his authority to control rather than to nurture. The reversed King can also represent a man who has been emotionally wounded and has closed himself off — cold, distant, and unable to receive love. In a reading, this card reversed warns against a man whose heart is not available or whose emotional expression is dishonest.", color: "red" },

  // ── DIAMONDS ──
  { id: 14, rank: "A", suit: "diamonds", name: "Ace of Diamonds", glyph: "🃁", element: "Earth", keywords: ["new money", "financial opportunity", "prosperity", "material beginning", "seed of wealth"], meaning: "The Ace of Diamonds is the seed of material prosperity and financial opportunity. This is the card of the new job offer, the investment opportunity, the inheritance, the raise, the business idea that will generate wealth. The Ace of Diamonds represents pure potential in the material realm — a beginning that, if nurtured, can grow into substantial wealth. When this card appears, a financial door is opening. You may receive a check, a bonus, a gift, or news of a money matter that requires your attention. Unlike the Ace of Spades (which cuts) or the Ace of Clubs (which ignites), the Ace of Diamonds builds. Financial foundations are laid with this card. It is a green light for material ventures, practical investments, and any endeavor that requires capital. The energy is solid, grounded, and quietly optimistic.", reversedMeaning: "The Ace of Diamonds reversed indicates missed financial opportunities, poor investments, or money that slips through your fingers. A promised payment may be delayed, a business deal may fall through, or a financial risk may not pay off. This card reversed warns against greed or taking unnecessary financial risks. It can also indicate anxiety about money, fear of financial instability, or a reluctance to invest in yourself financially. The potential exists but is blocked; the seed cannot germinate in barren soil.", color: "red" },
  { id: 15, rank: "2", suit: "diamonds", name: "Two of Diamonds", glyph: "🃂", element: "Earth", keywords: ["balance", "budgeting", "juggling finances", "priorities", "resource management"], meaning: "The Two of Diamonds represents the balancing act required to manage multiple financial obligations. This is the card of the budget, the spreadsheet, the careful allocation of limited resources. You may be juggling bills, managing debts while saving for a goal, or weighing two financial options against each other. The Two of Diamonds is not about abundance or lack — it is about making choices with what you have. This card often appears when you need to review your financial priorities or when a financial decision requires careful deliberation. The energy is practical and measured; there is no rush. Take the time to get the numbers right. The Two of Diamonds does not promise wealth, but it promises that careful management will prevent loss.", reversedMeaning: "The Two of Diamonds reversed indicates financial imbalance, disorganization, or avoidance of financial realities. You may be ignoring bills, overspending, or failing to budget. The reverse warns that financial chaos will lead to loss if you do not take control. It can also indicate a difficult choice between two financial paths where neither seems ideal. The balance is lost; the accounts need attention.", color: "red" },
  { id: 16, rank: "3", suit: "diamonds", name: "Three of Diamonds", glyph: "🃃", element: "Earth", keywords: ["teamwork", "collaboration", "skilled trade", "craftsmanship", "partnership"], meaning: "The Three of Diamonds represents collaborative work in the material realm. This is the card of the successful partnership, the team project, the joint venture that combines skills and resources for mutual financial benefit. It can indicate a business partnership, a collaborative project at work, or a financial arrangement that requires input from multiple parties. The Three of Diamonds suggests that your financial success may come through working with others rather than going it alone. Someone has skills that complement yours, and together you can create something neither could achieve independently. The energy is cooperative, professional, and focused on practical outcomes.", reversedMeaning: "The Three of Diamonds reversed indicates a partnership that is not working, financial disagreements among collaborators, or a team project that is failing due to poor communication. Someone may not be pulling their weight, or there may be disputes over money within a group. This card reversed warns against entering into financial partnerships without clear agreements. It can also indicate that going it alone is the better choice for now.", color: "red" },
  { id: 17, rank: "4", suit: "diamonds", name: "Four of Diamonds", glyph: "🃄", element: "Earth", keywords: ["savings", "financial security", "reserves", "wealth", "possession"], meaning: "The Four of Diamonds represents financial stability, savings, and material security. This is the card of the emergency fund, the retirement account, the paid-off debt, the asset that generates passive income. The Four of Diamonds is the most stable card in the Diamonds suit — it speaks not of wealth that comes and goes but of wealth that stays. When this card appears, you are financially secure or close to it. Your basic needs are met, and you have reserves for unexpected expenses. This card encourages prudent saving and the wise management of existing resources. It is not a card of risk or expansion; it is the card of preservation and protection. Hold what you have; do not squander your security on unproven ventures.", reversedMeaning: "The Four of Diamonds reversed indicates financial insecurity, depleted savings, or a loss of material stability. You may be living paycheck to paycheck, drawing down your reserves, or facing an unexpected expense that depletes your cushion. This card reversed warns against hoarding money out of fear — sometimes the need to spend is genuine and necessary. It can also indicate that your attachment to material security is preventing you from taking a necessary risk.", color: "red" },
  { id: 18, rank: "5", suit: "diamonds", name: "Five of Diamonds", glyph: "🃅", element: "Earth", keywords: ["financial loss", "hardship", "exclusion", "material challenge", "lack"], meaning: "The Five of Diamonds represents material hardship, financial loss, or the experience of being excluded from prosperity that others enjoy. This is the card of the unpaid bill, the declined loan, the job loss, the business failure. Unlike the Ace of Diamonds which promises new money, the Five of Diamonds speaks to the loss of money. This card can be deeply unsettling, especially when it appears in a reading about finances. However, the Five of Diamonds also carries a hidden gift: it humbles, teaches resilience, and often reorients your relationship with money. Those who have lost everything and rebuilt understand the true value of a dollar. This card asks you to reach out for support — pride will only deepen the loss. Financial hardship is not a moral failing; it is a temporary condition.", reversedMeaning: "The Five of Diamonds reversed indicates that the worst of the financial hardship is over. You have hit rock bottom and are beginning to climb back up. Alternatively, it can indicate that you are avoiding a financial reality — refusing to look at your bank account, ignoring debts, or denying that a loss has occurred. The reverse asks you to face the numbers honestly so that recovery can begin.", color: "red" },
  { id: 19, rank: "6", suit: "diamonds", name: "Six of Diamonds", glyph: "🃆", element: "Earth", keywords: ["generosity", "charity", "fair exchange", "giving", "receiving"], meaning: "The Six of Diamonds represents generosity, fair exchange, and the flow of resources between people. This is the card of the gift, the donation, the loan repaid, the fair wage for honest work. The Six of Diamonds speaks to the principle that money flows in cycles — what you give returns to you, and what you receive is meant to be shared. When this card appears, you may be in a position to help someone financially, or you may need to accept help from others. The Six of Diamonds asks you to examine your relationship with giving and receiving. Do you give freely, or with strings attached? Do you receive graciously, or with guilt? The energy is generous, open-handed, and trusting that the flow of resources is abundant.", reversedMeaning: "The Six of Diamonds reversed indicates unfair exchanges, debts not repaid, or a miserly attitude toward money. Someone may be taking advantage of your generosity, or you may be the one who is not sharing fairly. The reverse warns against enabling financial dependency in others — sometimes the most generous thing you can do is say no. It can also indicate a gift with strings attached, or charity that comes with conditions.", color: "red" },
  { id: 20, rank: "7", suit: "diamonds", name: "Seven of Diamonds", glyph: "🃇", element: "Earth", keywords: ["patience", "investment", "long-term growth", "harvest", "assessment"], meaning: "The Seven of Diamonds represents patience, long-term investment, and the wisdom to wait for returns. This is the card of the farmer who plants in spring and trusts that the harvest will come in autumn. In financial terms, it represents investments that grow over time, savings that compound, and strategies that require patience rather than quick wins. The Seven of Diamonds counsels against get-rich-quick schemes and encourages steady, disciplined financial planning. When this card appears, you may be waiting for a financial outcome that is taking longer than expected. This card assures you that the investment is sound — the harvest will come, but only if you do not dig up the seeds to check on them. Trust the process and stay the course.", reversedMeaning: "The Seven of Diamonds reversed indicates impatience with financial progress, poor investment choices, or a desire for immediate gratification at the expense of long-term stability. You may be tempted to cash out early, abandon a sound plan, or chase a risky opportunity out of frustration. The reverse warns that impatience in financial matters leads to loss. Alternatively, it can indicate that you have been waiting too long and it is time to cut your losses and move on.", color: "red" },
  { id: 21, rank: "8", suit: "diamonds", name: "Eight of Diamonds", glyph: "🃈", element: "Earth", keywords: ["apprenticeship", "skill building", "diligence", "mastery", "learning"], meaning: "The Eight of Diamonds represents the diligent work of learning a skill, mastering a craft, or building expertise that will generate future income. This is the card of the apprentice, the student, the person who is investing time and effort to become proficient. The Eight of Diamonds acknowledges that financial success often requires an investment of time and learning before the money begins to flow. When this card appears, you may be in training, studying for a certification, learning a trade, or developing a skill that will increase your earning potential. The work may be tedious, but every hour invested increases your value. The Eight of Diamonds counsels patience and persistence — mastery is not achieved overnight, but it is achieved by those who keep showing up.", reversedMeaning: "The Eight of Diamonds reversed indicates a lack of diligence, a skill that is not being developed, or a wasted opportunity for growth. You may be avoiding the hard work required to improve your financial situation, cutting corners, or giving up too easily on learning something new. The reverse warns that without skill development, your earning potential will stagnate. Alternatively, it can indicate that you are overworked and undervalued — your skills are being exploited rather than compensated fairly.", color: "red" },
  { id: 22, rank: "9", suit: "diamonds", name: "Nine of Diamonds", glyph: "🃉", element: "Earth", keywords: ["self-sufficiency", "luxury", "reward", "abundance", "financial freedom"], meaning: "The Nine of Diamonds represents financial self-sufficiency, earned luxury, and the reward of hard work. This is the card of the person who has built their own prosperity through skill, discipline, and perseverance. The Nine of Diamonds is not inherited wealth or lucky money — it is what you have earned. When this card appears, you are reaping the rewards of your efforts. You may be debt-free, enjoying the fruits of a successful project, or finally in a position where money is not a source of anxiety. The Nine of Diamonds encourages you to enjoy your prosperity without guilt. You earned it. The energy is confident, independent, and quietly proud. This card can also indicate a bonus, a commission, or a professional achievement that brings financial recognition.", reversedMeaning: "The Nine of Diamonds reversed indicates financial insecurity despite hard work, or a sense that your efforts are not being properly compensated. You may be struggling even though you are doing everything right, or you may have achieved financial comfort but find it unsatisfying. The reverse warns against equating self-worth with net worth. It can also indicate overspending on luxury items as a way to fill an emotional void, or a fear that your prosperity will be taken away.", color: "red" },
  { id: 23, rank: "10", suit: "diamonds", name: "Ten of Diamonds", glyph: "🃊", element: "Earth", keywords: ["legacy", "inheritance", "family wealth", "enduring value", "foundation"], meaning: "The Ten of Diamonds represents legacy wealth, inheritance, and financial foundations that endure across generations. This is the card of the family business, the trust fund, the estate, the wealth that outlives the person who built it. The Ten of Diamonds speaks to what you leave behind materially — not just money, but property, investments, and financial security for your descendants. When this card appears, you may be dealing with an inheritance, planning your estate, or considering how to build wealth that lasts beyond your lifetime. It can also indicate receiving financial support from family or a significant material gift that changes your circumstances. The energy is solid, enduring, and connected to family legacy. The Ten of Diamonds reminds you that financial decisions today create the foundation for future generations.", reversedMeaning: "The Ten of Diamonds reversed indicates family conflict over money, an inheritance that causes more problems than it solves, or a legacy of financial dysfunction. There may be disputes over a will, unequal distribution of assets, or a family business that is failing. The reverse warns against the belief that money alone can secure a family's future — without love and communication, wealth can divide rather than unite. It can also indicate that you are not receiving the financial support you need from your family.", color: "red" },
  { id: 24, rank: "J", suit: "diamonds", name: "Jack of Diamonds", glyph: "🃋", element: "Earth", keywords: ["young entrepreneur", "financial news", "opportunity", "resourceful youth", "messenger"], meaning: "The Jack of Diamonds represents a young person with business acumen, financial news, or an entrepreneurial opportunity. This is the card of the young entrepreneur, the intern who impresses everyone, the person who sees money-making opportunities where others see nothing. The Jack of Diamonds brings news of a financial nature: an invoice paid, a job offer, a business lead, a tip about an investment. The energy is fast, opportunistic, and practical. When this card appears, pay attention to conversations and messages — a young person may have valuable financial advice, or an opportunity may present itself through a younger colleague, student, or family member. The Jack of Diamonds does not guarantee success, but it guarantees that the opportunity is worth investigating.", reversedMeaning: "The Jack of Diamonds reversed indicates a missed financial opportunity, bad financial advice from a young or inexperienced person, or immaturity in handling money. Someone may be promising financial returns they cannot deliver. The reverse warns against get-rich-quick schemes or trusting financial advice from those who lack experience. It can also indicate procrastination on a financial matter that will cost you if delayed further.", color: "red" },
  { id: 25, rank: "Q", suit: "diamonds", name: "Queen of Diamonds", glyph: "🃍", element: "Earth", keywords: ["practical woman", "social grace", "financial independence", "sophistication", "resource manager"], meaning: "The Queen of Diamonds represents a woman who is financially independent, socially graceful, and materially sophisticated. This is the card of the businesswoman, the banker, the real estate investor, the woman who has built her own wealth and knows how to manage it. The Queen of Diamonds is elegant, practical, and shrewd. She understands that money is a tool, not a goal — but she also understands that having money gives her the freedom to live life on her terms. When this card appears, it may represent a specific woman (usually dark-haired or practical in nature) or the querent's own capacity for financial wisdom and material self-sufficiency. The Queen of Diamonds counsels practical decision-making, thoughtful investment, and maintaining a standard of living that reflects your values.", reversedMeaning: "The Queen of Diamonds reversed indicates a woman who is materialistic, greedy, or financially reckless. She may be obsessed with status and appearances, spending beyond her means to project an image of wealth she does not actually have. The reversed Queen can also represent a woman who is financially dependent on others or who uses money to control people. In a reading, this card reversed asks you to examine your own relationship with money and whether you are using it as a tool or allowing it to define you.", color: "red" },
  { id: 26, rank: "K", suit: "diamonds", name: "King of Diamonds", glyph: "🃎", element: "Earth", keywords: ["financial authority", "business leader", "wealth", "provider", "mastery"], meaning: "The King of Diamonds represents a man of financial authority, business success, and material mastery. This is the card of the CEO, the investor, the banker, the entrepreneur who has built an empire. The King of Diamonds has mastered the material realm — he understands money, markets, and the art of the deal. He is generous but not foolish, strategic but not cold. When this card appears, it may represent a specific man (usually older, dark-haired, or financially successful) or the querent's own capacity for financial leadership. The King of Diamonds counsels strategic thinking in business matters, confidence in financial decisions, and the responsibility that comes with wealth. He reminds you that money is a responsibility as much as a reward — those who master money can use it to create value for others.", reversedMeaning: "The King of Diamonds reversed indicates a man who is financially reckless, greedy, or dishonest. He may be involved in shady deals, using money to manipulate others, or losing wealth through poor judgment. The reversed King can also represent a man who is bankrupt — financially, morally, or both. In a reading, this card reversed warns against placing your financial trust in someone who has not earned it. It can also indicate that your own relationship with money has become unbalanced — you may be chasing wealth at the expense of everything else.", color: "red" },

  // ── CLUBS ──
  { id: 27, rank: "A", suit: "clubs", name: "Ace of Clubs", glyph: "🃑", element: "Fire", keywords: ["new idea", "creative spark", "inspiration", "beginning", "potential"], meaning: "The Ace of Clubs is the seed of creative inspiration, intellectual fire, and new enterprise. This is the card of the brilliant idea, the creative breakthrough, the project that ignites your passion. The Ace of Clubs is pure creative potential — a spark that, if nurtured, can grow into something significant. When this card appears, a new idea is being born. You may feel a surge of inspiration, a desire to create, or a call to start something ambitious. Unlike the Ace of Diamonds (which is about money) or the Ace of Hearts (which is about love), the Ace of Clubs is about creation itself — writing, building, inventing, designing, launching. The energy is exciting, vital, and full of possibility. The Ace of Clubs asks you to pay attention to the ideas that excite you; they are the seeds of your future work.", reversedMeaning: "The Ace of Clubs reversed indicates a creative block, an idea that cannot get off the ground, or a lack of inspiration. You may be feeling uninspired, stuck in a creative rut, or unable to generate the spark you need. The reverse warns against forcing creativity — sometimes the spark will not come until you rest. It can also indicate a good idea that is poorly executed or a project that starts with enthusiasm but fizzles out quickly due to lack of planning.", color: "black" },
  { id: 28, rank: "2", suit: "clubs", name: "Two of Clubs", glyph: "🃒", element: "Fire", keywords: ["planning", "consideration", "partnership decisions", "weighing options", "strategy"], meaning: "The Two of Clubs represents the planning phase of a creative or professional project. This is the card of the blueprint, the strategy session, the careful weighing of options before action. You have the idea (the Ace); now you need to figure out how to execute it. The Two of Clubs speaks to partnerships formed around creative or professional goals — two people combining their strengths to bring an idea to life. When this card appears, you are in a decision-making phase. You may be choosing between two approaches, interviewing potential collaborators, or deciding whether to commit to a project. The energy is thoughtful and measured. Do not rush into action; take the time to plan properly. The Two of Clubs asks you to consider all angles before proceeding.", reversedMeaning: "The Two of Clubs reversed indicates indecision, poor planning, or a partnership that is not aligned on goals. You may be rushing into a project without adequate preparation, or you may be stuck in analysis paralysis, unable to move forward. The reverse warns against entering into professional partnerships without clear agreements about roles, responsibilities, and creative direction. The plan is incomplete; revisit the drawing board before committing resources.", color: "black" },
  { id: 29, rank: "3", suit: "clubs", name: "Three of Clubs", glyph: "🃓", element: "Fire", keywords: ["collaboration", "enterprise", "expansion", "teamwork", "joint venture"], meaning: "The Three of Clubs represents collaboration, joint enterprise, and the power of a team working toward a shared creative or professional goal. This is the card of the startup, the creative collective, the team of people who together can achieve what none could alone. The Three of Clubs suggests that your current project or creative endeavor will benefit from bringing in others. You do not have to do it all yourself. When this card appears, a group effort is taking shape — a band forming, a business partnership solidifying, a creative team coming together. The energy is collaborative, dynamic, and full of possibility. The Three of Clubs assures you that the whole is greater than the sum of its parts.", reversedMeaning: "The Three of Clubs reversed indicates a team that is not functioning well, creative differences, or a group project that is failing due to poor communication. There may be competition within the group, conflicting visions, or one person dominating the creative direction. The reverse warns that collaboration requires compromise and clear communication. If the group cannot find alignment, going solo may be the better choice.", color: "black" },
  { id: 30, rank: "4", suit: "clubs", name: "Four of Clubs", glyph: "🃔", element: "Fire", keywords: ["structure", "foundation", "community", "stability", "order"], meaning: "The Four of Clubs represents structure, community, and the creation of systems that support creative work. This is the card of the studio, the workshop, the office, the routine that makes consistent creative output possible. The Four of Clubs speaks to the importance of building a stable foundation for your creative or professional life. When this card appears, you may be establishing a routine, setting up a workspace, joining a professional community, or creating the structures that will support your long-term creative goals. The energy is organized, grounded, and practical. Creativity needs structure to flourish; the Four of Clubs provides it. This card can also indicate being part of a professional organization, a guild, or a community of practice that provides support and accountability.", reversedMeaning: "The Four of Clubs reversed indicates instability in your creative or professional life, a lack of structure, or a community that is not supportive. Your work space may be chaotic, your schedule may be unreliable, or the professional community you thought you belonged to may not have your back. The reverse warns that without structure, your creative energy will dissipate. It can also indicate becoming too rigid — so focused on systems and routines that there is no room for spontaneity or inspiration.", color: "black" },
  { id: 31, rank: "5", suit: "clubs", name: "Five of Clubs", glyph: "🃕", element: "Fire", keywords: ["conflict", "competition", "struggle", "challenge", "rivalry"], meaning: "The Five of Clubs represents conflict, competition, and the struggle that arises when creative or professional visions clash. This is the card of the competitive workplace, the creative disagreement, the battle for resources or recognition. Unlike the Five of Spades (which is about betrayal and defeat), the Five of Clubs is about productive conflict — the friction that can sharpen ideas and strengthen outcomes. When this card appears, you may be facing opposition to your ideas, competing for a promotion or project, or in a dispute with a colleague or collaborator. The Five of Clubs asks you to stand your ground but choose your battles wisely. Not every disagreement needs to be a war. The energy is challenging but potentially productive if channeled constructively.", reversedMeaning: "The Five of Clubs reversed indicates a conflict that has gone on too long, a competitive situation that has become toxic, or a battle that was not worth fighting. You may be exhausted from constant struggle, or you may have lost a professional rivalry and need to accept it. The reverse warns against letting competition consume you — there is a difference between healthy challenge and destructive conflict. It can also indicate avoiding a necessary confrontation that will only get worse if ignored.", color: "black" },
  { id: 32, rank: "6", suit: "clubs", name: "Six of Clubs", glyph: "🃖", element: "Fire", keywords: ["victory", "recognition", "success", "accomplishment", "validation"], meaning: "The Six of Clubs represents victory, recognition, and the public acknowledgment of achievement. This is the card of the promotion, the award, the published work, the successful launch. The Six of Clubs arrives after the struggle of the Fives and brings the sweet taste of success. When this card appears, your hard work is being recognized. You may receive a promotion, win a contract, be praised for your work, or achieve a goal that has required sustained effort. The energy is triumphant and validating. The Six of Clubs encourages you to accept recognition graciously and to celebrate your achievements. You have earned this moment. In a reading, it can also indicate good news arriving about a creative or professional matter — a call, a letter, or an announcement that confirms your success.", reversedMeaning: "The Six of Clubs reversed indicates delayed recognition, success that feels hollow, or an achievement that goes unnoticed. You may have worked hard but not received the credit you deserve, or a promotion or award may be postponed. The reverse warns against tying your self-worth to external validation — your accomplishments are real whether or not anyone claps. It can also indicate that success has come at too high a price, or that you are resting on past laurels rather than continuing to grow.", color: "black" },
  { id: 33, rank: "7", suit: "clubs", name: "Seven of Clubs", glyph: "🃗", element: "Fire", keywords: ["perseverance", "defense", "standing ground", "resilience", "determination"], meaning: "The Seven of Clubs represents perseverance in the face of opposition and the determination to defend your position. This is the card of the underdog, the person who keeps fighting despite the odds, the stance you take when everything is on the line. The Seven of Clubs appears when you are being challenged professionally or creatively and you must decide whether to stand your ground or retreat. When this card appears, you may be in a situation where your ideas, your work, or your reputation is under attack. The Seven of Clubs encourages you to hold your position but to choose your battles wisely. Sometimes the wisest defense is to refuse to engage. The energy is resilient, determined, and strategically defensive. This card assures you that you have what it takes to weather this challenge.", reversedMeaning: "The Seven of Clubs reversed indicates that your defenses are failing or that you have taken a stand that is not worth defending. You may be fighting a losing battle, exhausting yourself in a situation that cannot be won, or defending a position that you do not actually believe in. The reverse warns against stubbornness disguised as principle. It can also indicate that it is time to retreat, regroup, and choose a different approach. Surrender is not always defeat; sometimes it is wisdom.", color: "black" },
  { id: 34, rank: "8", suit: "clubs", name: "Eight of Clubs", glyph: "🃘", element: "Fire", keywords: ["speed", "movement", "communication", "messages", "travel"], meaning: "The Eight of Clubs represents swift movement, rapid communication, and the speed at which information travels in the modern world. This is the card of the urgent email, the text message, the phone call that changes everything, the news that arrives fast and requires immediate attention. When this card appears, things are moving quickly in your creative or professional life. A project may be accelerating, a decision may need to be made rapidly, or important information may be incoming. The Eight of Clubs counsels staying alert and responsive. Opportunities in this card's energy are fleeting — if you do not act quickly, the moment may pass. In travel readings, it indicates a short trip or a journey for business or creative purposes. The energy is fast, stimulating, and slightly urgent.", reversedMeaning: "The Eight of Clubs reversed indicates delayed messages, slow progress, or communication that is stuck. An expected email or call may not arrive on time, a project may be stalled, or travel plans may be delayed. The reverse warns against rushing when circumstances are not ready — forcing speed when the universe is asking for patience will lead to mistakes. It can also indicate miscommunication, messages that are sent but not received, or important information that gets lost in transit.", color: "black" },
  { id: 35, rank: "9", suit: "clubs", name: "Nine of Clubs", glyph: "🃙", element: "Fire", keywords: ["resilience", "boundaries", "endurance", "last stand", "inner strength"], meaning: "The Nine of Clubs represents the inner strength that comes from having endured great challenges. This is the card of the survivor, the person who has been tested by fire and emerged stronger. The Nine of Clubs speaks to the boundaries you have built to protect yourself and the resilience that allows you to keep going when others would have given up. When this card appears, you may be in the final stretch of a long struggle, making a last stand for something you believe in, or realizing that your boundaries have been tested and held. The Nine of Clubs assures you that you are stronger than you know. The energy is fiercely independent, protective, and quietly triumphant. This card does not promise that the struggle is over, but it promises that you have what it takes to see it through.", reversedMeaning: "The Nine of Clubs reversed indicates that your boundaries have been breached, your resilience is depleted, or you are exhausted from constant struggle. You may feel like you cannot take any more, or that the walls you built to protect yourself have crumbled. The reverse warns against isolating yourself in the name of protection — sometimes strength means letting others help you. It can also indicate that the stand you are taking is actually a refusal to grow, and the walls you have built are keeping out not just harm but also love and opportunity.", color: "black" },
  { id: 36, rank: "10", suit: "clubs", name: "Ten of Clubs", glyph: "🃚", element: "Fire", keywords: ["burden", "responsibility", "overwhelm", "pressure", "obligation"], meaning: "The Ten of Clubs represents the burden of responsibility, professional overwhelm, and the weight of carrying too much. This is the card of the overworked professional, the entrepreneur who cannot delegate, the creative who has taken on too many projects. The Ten of Clubs speaks to the pressure that comes with success — the more you achieve, the more is expected of you. When this card appears, you may be feeling overwhelmed by your obligations. There are too many deadlines, too many demands, too much on your plate. The Ten of Clubs warns that carrying this load alone will lead to burnout. You need to delegate, prioritize, or release something. The energy is heavy but not hopeless — the Ten of Clubs is the final weight before rest. Once you lighten the load, relief is on the other side.", reversedMeaning: "The Ten of Clubs reversed indicates that the burden has become unbearable, or that you have reached a point of burnout and breakdown. You may have already collapsed under the weight of your responsibilities, or you may be in denial about how overwhelmed you truly are. The reverse warns that ignoring the signs of burnout will lead to physical or mental health consequences. It can also indicate that you have dropped a responsibility that was not yours to carry, which is ultimately positive — the release, even if forced, is necessary for your survival.", color: "black" },
  { id: 37, rank: "J", suit: "clubs", name: "Jack of Clubs", glyph: "🃛", element: "Fire", keywords: ["young messenger", "student", "enthusiasm", "news", "beginner's mind"], meaning: "The Jack of Clubs represents a young person with creative or intellectual ambition, a message about a project or idea, or the enthusiastic energy of a beginner. This is the card of the eager intern, the passionate student, the young artist who has not yet been jaded by the world. The Jack of Clubs brings news of a creative or professional nature: an idea, an invitation, a learning opportunity. When this card appears, a young person may play an important role in your creative or professional life, or you may need to approach a situation with the open, curious energy of a beginner. The Jack of Clubs encourages you to stay enthusiastic, ask questions, and remain open to learning. The energy is fresh, optimistic, and full of potential — not yet burdened by the weight of experience.", reversedMeaning: "The Jack of Clubs reversed indicates a young person who is unreliable, overly confident without the skills to back it up, or a message that brings bad news about a project. The reverse warns against naivety or taking on a project without adequate preparation. A young person in your professional life may not be ready for the responsibility they have been given. It can also indicate creative insecurity, fear of putting your work into the world, or a project that starts with enthusiasm but cannot be finished.", color: "black" },
  { id: 38, rank: "Q", suit: "clubs", name: "Queen of Clubs", glyph: "🃝", element: "Fire", keywords: ["confident woman", "charismatic", "independent", "creative leader", "magnetic"], meaning: "The Queen of Clubs represents a woman of creative confidence, charisma, and professional independence. This is the card of the artist, the designer, the creative director, the woman who has built a career around her vision. The Queen of Clubs is magnetic, self-assured, and unapologetically herself. She leads through the power of her personality and the clarity of her creative vision. When this card appears, it may represent a specific woman (usually with a strong creative presence) or the querent's own capacity for confident creative expression. The Queen of Clubs counsels trusting your creative instincts, leading with confidence, and not dimming your light to make others comfortable. She is the artist who knows her worth and does not apologize for it.", reversedMeaning: "The Queen of Clubs reversed indicates a woman who is creatively blocked, overly domineering in collaborative settings, or using her charisma to manipulate. She may have lost confidence in her creative abilities, or her ego may be preventing her from seeing clearly. The reversed Queen can also represent a woman who is so focused on her own vision that she cannot hear others' contributions. In a reading, this card reversed asks whether your creative confidence has become arrogance, or whether insecurity is preventing you from sharing your gifts with the world.", color: "black" },
  { id: 39, rank: "K", suit: "clubs", name: "King of Clubs", glyph: "🃞", element: "Fire", keywords: ["visionary leader", "authority", "commanding", "innovator", "ambition"], meaning: "The King of Clubs represents a man of creative vision, professional authority, and commanding presence. This is the card of the visionary entrepreneur, the creative director, the leader who inspires others through the power of his ideas. The King of Clubs has built his career on his own terms — he is an innovator, a risk-taker, and a natural leader. When this card appears, it may represent a specific man (usually with strong creative or professional authority) or the querent's own capacity for visionary leadership. The King of Clubs counsels bold action, confident decision-making, and the courage to lead even when the path is unclear. He reminds you that true leadership requires both vision and the willingness to take responsibility for bringing that vision into reality.", reversedMeaning: "The King of Clubs reversed indicates a man who abuses his professional authority, a leader whose vision is flawed, or someone who uses power to dominate rather than inspire. He may be arrogant, closed to feedback, or leading his team in the wrong direction. The reversed King can also represent a creative person who has become cynical or burned out, losing the passion that once drove him. In a reading, this card reversed warns against following someone whose vision you do not trust, and asks whether your own ambition has become ruthless.", color: "black" },

  // ── SPADES ──
  { id: 40, rank: "A", suit: "spades", name: "Ace of Spades", glyph: "🂡", element: "Air", keywords: ["truth", "clarity", "cut", "ending", "revelation", "breakthrough"], meaning: "The Ace of Spades is the most powerful card in the deck. It represents truth, clarity, and the decisive cut that separates what is real from what is false. The Ace of Spades is the card of necessary endings, surgical precision, and the kind of clarity that comes only when illusions are stripped away. Unlike the gentle end of the Five of Hearts, the Ace of Spades cuts swiftly and cleanly. When this card appears, something must end — a lie, a situation, a relationship that is no longer true. The ending may be sudden, but it is necessary. The Ace of Spades carries the energy of the sword: sharp, decisive, and impartial. It brings mental clarity and the courage to face the truth, even when it hurts. In health readings, it can indicate surgery or a medical intervention. In legal matters, it represents the final verdict. The Ace of Spades is not cruel — it is honest. And honesty, ultimately, is the most compassionate gift.", reversedMeaning: "The Ace of Spades reversed indicates denial of truth, avoidance of a necessary ending, or a truth that is being suppressed. You may know that something needs to end but cannot bring yourself to make the cut. The reverse warns that avoiding the truth will only make the eventual reckoning more painful. Alternatively, it can indicate a sudden, unexpected ending that catches you off guard — a death, a breakup, a job loss that you did not see coming. The Ace of Spades reversed asks what truth you are refusing to face.", color: "black" },
  { id: 41, rank: "2", suit: "spades", name: "Two of Spades", glyph: "🂢", element: "Air", keywords: ["stalemate", "difficult choice", "indecision", "standoff", "equilibrium"], meaning: "The Two of Spades represents a stalemate, a difficult choice, or a situation where you are caught between two equally challenging options. This is the card of the crossroads when neither path is easy and you cannot stand still. The Two of Spades speaks to the tension of being pulled in two directions — two loyalties, two obligations, two fears. When this card appears, you are facing a decision that requires you to choose between two things that both matter. The energy is tense, balanced on a knife's edge. The Two of Spades does not tell you which choice is right; it tells you that not choosing is itself a choice, and usually the worst one. The stalemate must be broken. Seek clarity, trust your intelligence to find a third way, or accept that both options carry loss and choose the one whose loss you can live with.", reversedMeaning: "The Two of Spades reversed indicates that the stalemate has been broken — a decision has been made or forced upon you. The tension is resolving, though not necessarily in your favor. Alternatively, the reverse can indicate that you are avoiding a decision so completely that you are pretending the choice does not exist. The reverse asks you to stop pretending and make the call. It can also indicate a truce or compromise after a period of conflict.", color: "black" },
  { id: 42, rank: "3", suit: "spades", name: "Three of Spades", glyph: "🂣", element: "Air", keywords: ["heartbreak", "separation", "sorrow", "grief", "loss"], meaning: "The Three of Spades represents heartbreak, separation, and the pain of losing someone or something you love. This is the card of the breakup, the divorce, the friend who walks away, the death of a relationship. The Three of Spades cuts deeply because the separation was not entirely clean — there is unfinished business, words left unsaid, or a bond that was severed before it was ready to be released. When this card appears, you are experiencing or will experience a painful separation. The grief is real and must be honored. The Three of Spades does not offer comfort or try to minimize the pain. What it offers is the assurance that the heart, though broken, continues to beat. Grief is the price of love, and the Three of Spades is the receipt. Allow yourself to mourn. Do not rush through this pain; it will teach you what you need to learn.", reversedMeaning: "The Three of Spades reversed indicates that the worst of the grief has passed. The acute pain of separation is fading, and you are beginning to heal. Alternatively, the reverse can indicate that you have not allowed yourself to grieve — you are suppressing the pain, pretending to be fine when you are not. The reverse warns that unprocessed grief will surface eventually, often in unhealthy ways. Allow yourself to feel what you have been avoiding.", color: "black" },
  { id: 43, rank: "4", suit: "spades", name: "Four of Spades", glyph: "🂤", element: "Air", keywords: ["rest", "recuperation", "meditation", "healing", "retreat"], meaning: "The Four of Spades represents rest, recuperation, and the sacred need for stillness after a period of struggle. This is the card of the convalescent, the person recovering from illness or heartbreak, the mind that needs to rest from constant thinking. The Four of Spades appears after the battles of the Threes and Fives, offering a necessary pause. When this card appears, you are being called to rest. Not to give up, not to escape, but to recharge. The Four of Spades recognizes that you have been through something difficult and your body, mind, and spirit need time to recover. This card often indicates a period of solitude, meditation, or quiet reflection. It is a card of healing and the wisdom that comes from stillness. Honor your need for rest — the world will wait.", reversedMeaning: "The Four of Spades reversed indicates an inability to rest, a refusal to slow down, or restlessness that prevents healing. You may be pushing yourself too hard, refusing to take the time you need to recover. The reverse warns that ignoring your need for rest will lead to breakdown. Alternatively, it can indicate that the period of rest has gone on too long and it is time to re-engage with the world. The retreat is over; the healing is complete enough to return.", color: "black" },
  { id: 44, rank: "5", suit: "spades", name: "Five of Spades", glyph: "🂥", element: "Air", keywords: ["conflict", "defeat", "betrayal", "hollow victory", "dishonor"], meaning: "The Five of Spades represents conflict that has become destructive, a hollow victory, or betrayal by someone you trusted. This is the most negative card in the Spades suit — it speaks to battles that should never have been fought, victories that cost more than they are worth, and the bitter taste of betrayal. When this card appears, you may be in a conflict that is escalating beyond reason. Someone may be acting against your interests, or you may be the one behaving dishonorably. The Five of Spades warns that winning at any cost is not winning at all. If you are fighting, ask yourself whether this battle is worth the damage it will cause. If you have already been betrayed, the Five of Spades validates your pain and asks you to walk away with your dignity intact. Not every fight deserves your energy.", reversedMeaning: "The Five of Spades reversed indicates that a destructive conflict is ending, or that you have narrowly avoided a betrayal. The worst is over, but the scars remain. Alternatively, the reverse can indicate that you have been the one causing harm and it is time to take responsibility for your actions. The Five of Spades reversed asks you to lay down your weapons and seek peace, even if the peace is imperfect. The battle has cost enough already.", color: "black" },
  { id: 45, rank: "6", suit: "spades", name: "Six of Spades", glyph: "🂦", element: "Air", keywords: ["transition", "moving on", "travel over water", "journey", "calmer waters"], meaning: "The Six of Spades represents transition, moving from troubled waters to calmer shores. This is the card of the journey away from difficulty, the physical or emotional move that carries you to a better place. The Six of Spades appears after the storms of the Five of Spades, offering a path forward. When this card appears, you are in transition. You may be moving to a new city, changing jobs, ending a difficult chapter, or simply making the inner journey from pain to peace. The journey may involve travel — especially over water — or it may be an emotional passage. The Six of Spades assures you that you are moving in the right direction. The waters ahead are calmer than the waters behind. Do not look back; what is behind you is no longer your destination.", reversedMeaning: "The Six of Spades reversed indicates a transition that is stuck, a journey that has been delayed, or movement that takes you in the wrong direction. You may be trying to move on but circumstances keep pulling you back. The reverse warns against running away from your problems — a change of location does not heal what is inside. Alternatively, it can indicate that the period of transition is ending and stability is returning. The boat has reached the shore; it is time to disembark.", color: "black" },
  { id: 46, rank: "7", suit: "spades", name: "Seven of Spades", glyph: "🂧", element: "Air", keywords: ["deception", "strategy", "secrecy", "betrayal", "stealth"], meaning: "The Seven of Spades represents deception, strategy, and the shadow side of intelligence. This is the card of the lie, the secret, the hidden agenda, the person who is not what they seem. The Seven of Spades warns against trusting too easily or taking things at face value. Someone may not be honest with you, or you may not be honest with yourself. When this card appears, pay attention to what is not being said. Look for inconsistencies, trust your intuition, and verify information before acting. The Seven of Spades is not always malicious — sometimes strategy requires discretion, and not all secrets are harmful. But the card asks you to be discerning. If something feels off, it probably is. In a creative or professional context, the Seven of Spades can indicate a strategic advantage gained through careful planning and timing.", reversedMeaning: "The Seven of Spades reversed indicates that a deception is being revealed, a secret is coming to light, or that you have been caught in a lie. Truth emerges, whether you are ready for it or not. The reverse can also indicate that you are the one being deceived and are about to discover the truth. Alternatively, it can represent the wisdom that comes from having been deceived — you will not be fooled the same way twice.", color: "black" },
  { id: 47, rank: "8", suit: "spades", name: "Eight of Spades", glyph: "🂨", element: "Air", keywords: ["limitation", "self-restriction", "mental trap", "fear", "confinement"], meaning: "The Eight of Spades represents self-imposed limitations, mental traps, and the fears that keep you confined. This is the card of the prison that exists only in your mind — the beliefs, anxieties, and stories that tell you what you cannot do, cannot have, or cannot be. When this card appears, you are more trapped by your own thinking than by external circumstances. The Eight of Spades asks you to examine the limitations you have accepted as truth. Are you really stuck, or have you convinced yourself that you are? The lock on this prison is on the inside. The key is in your hand. This card is a wake-up call to recognize that the only real cage is the one you have built with your thoughts. Freedom is available the moment you choose to walk through the door.", reversedMeaning: "The Eight of Spades reversed indicates that you are beginning to break free from self-imposed limitations. The mental trap is loosening. You are recognizing that the fears and beliefs that held you were not as solid as they seemed. The reverse brings a wave of clarity and liberation — you can see the door now. However, the reverse can also indicate that the limitations are so deeply ingrained that you do not even see them. The most dangerous cage is the one you do not know you are in.", color: "black" },
  { id: 48, rank: "9", suit: "spades", name: "Nine of Spades", glyph: "🂩", element: "Air", keywords: ["anxiety", "worry", "insomnia", "despair", "nightmares"], meaning: "The Nine of Spades represents anxiety, worry, and the mental anguish that keeps you awake at night. This is the card of the 3 AM thoughts, the catastrophic imaginings, the fears that multiply in the dark. The Nine of Spades is the most mentally difficult card in the deck — it speaks to the suffering that happens entirely in the mind. When this card appears, you may be consumed by worry about a situation that has not yet happened. Your mind is creating worst-case scenarios and treating them as inevitable. The Nine of Spades asks you to recognize that most of what you fear never comes to pass. The suffering you are experiencing now is anticipation, not reality. This card is a call to ground yourself in the present moment, to distinguish between legitimate concern and spiraling anxiety, and to seek support if the mental burden is too heavy to carry alone.", reversedMeaning: "The Nine of Spades reversed indicates that the anxiety is lifting, that you have hit rock bottom mentally and are beginning to rise. The worst of the worry has passed, and you can see that things are not as bad as you feared. Alternatively, the reverse can indicate that you are in denial about your mental state — suppressing anxiety rather than addressing it. The Nine of Spades reversed asks you to take your mental health seriously, even if you feel you are \"fine.\" Healing requires honesty about what you are carrying.", color: "black" },
  { id: 49, rank: "10", suit: "spades", name: "Ten of Spades", glyph: "🂪", element: "Air", keywords: ["rock bottom", "crisis", "ending", "transformation", "release"], meaning: "The Ten of Spades represents rock bottom, crisis, and the kind of ending that is so complete it breaks you open. This is the card of the worst moment — the betrayal you did not see coming, the diagnosis you feared, the loss that changes everything. The Ten of Spades is often considered the most painful card in the deck, and it is. But it is also the card of transformation. The Ten of Spades speaks to the wisdom that comes only through complete devastation: the understanding that you can survive what you thought would kill you. When this card appears, something is ending in a way that feels catastrophic. But dawn is coming. In the Rider-Waite-Smith tarot, the Ten of Swords shows a figure pierced by ten swords — but the sky is brightening on the horizon. The same is true here. The Ten of Spades is the darkest moment, but it is also the turning point. From here, the only direction is up.", reversedMeaning: "The Ten of Spades reversed indicates that the crisis has passed and you are recovering from rock bottom. The worst is over. You have survived what you thought would destroy you, and you are now in the recovery phase. The reverse can also indicate that you are refusing to hit bottom — you keep trying to avoid the inevitable ending, prolonging your suffering. Sometimes you must let things fall apart so they can be rebuilt stronger. The reverse asks whether you are ready to release what is already over.", color: "black" },
  { id: 50, rank: "J", suit: "spades", name: "Jack of Spades", glyph: "🂫", element: "Air", keywords: ["young truth-teller", "sharp mind", "direct communication", "honesty", "intellectual"], meaning: "The Jack of Spades represents a young person with a sharp mind, direct communication, and an uncompromising commitment to truth. This is the card of the young intellectual, the journalist, the person who speaks truth to power without concern for popularity. The Jack of Spades brings news that cuts through illusion — often uncomfortable but always honest. When this card appears, you may receive information that is difficult to hear but necessary for your growth. Someone may speak to you with brutal honesty, or you may need to speak truthfully even though it will upset someone. The Jack of Spades encourages direct, honest communication without sugar-coating. The energy is sharp, clear, and unapologetic. This card is a reminder that the truth, even when painful, is always kinder in the long run than a comforting lie.", reversedMeaning: "The Jack of Spades reversed indicates gossip, cruel words, or a young person who uses their intellect to hurt others. The truth is being weaponized rather than offered with compassion. It can also indicate that you are avoiding saying something that needs to be said, or that harsh words have been spoken and cannot be taken back. The reverse warns that words have power — use them carefully, or they will be used against you. Alternatively, it can indicate bad news arriving that is delivered insensitively.", color: "black" },
  { id: 51, rank: "Q", suit: "spades", name: "Queen of Spades", glyph: "🂭", element: "Air", keywords: ["perceptive woman", "intuitive", "wise", "psychic", "truth-seeker"], meaning: "The Queen of Spades represents a woman of profound perception, sharp intuition, and unflinching honesty. This is the card of the psychic, the therapist, the wise woman who sees through pretense and speaks truth no matter how uncomfortable. The Queen of Spades has the gift of clarity — she sees what others miss, and she has the courage to name what she sees. When this card appears, it may represent a specific woman (usually dark-haired, perceptive, or psychologically astute) or the querent's own capacity for profound insight. The Queen of Spades counsels trusting your intuition, especially when you sense that something is not right. She is the part of you that knows before you have proof. In readings, she often appears when you need to access your own inner wisdom rather than seeking answers outside yourself. Her energy is direct, perceptive, and uncompromisingly truthful.", reversedMeaning: "The Queen of Spades reversed indicates a woman who uses her perceptiveness to manipulate, a person who is overly critical or judgmental, or someone whose intuition has become clouded by bitterness. The reversed Queen can also represent a woman who sees the truth but refuses to speak it, or who uses what she knows as a weapon. In a reading, this card reversed warns against trusting someone who seems perceptive but may have ulterior motives. It can also indicate that your own judgment is clouded by emotion or prejudice.", color: "black" },
  { id: 52, rank: "K", suit: "spades", name: "King of Spades", glyph: "🂮", element: "Air", keywords: ["authority", "judgment", "legal matters", "justice", "intellectual power"], meaning: "The King of Spades represents a man of intellectual authority, judgment, and decisive action. This is the card of the judge, the lawyer, the surgeon, the CEO who makes hard decisions — the man who must carry the weight of authority and wield it justly. The King of Spades has mastered the realm of the mind; he is analytical, strategic, and unswayed by emotion. When this card appears, it may represent a specific man (usually older, authoritative, or involved in legal matters) or the querent's own capacity for clear judgment and decisive action. The King of Spades counsels making decisions with your head, not your heart, especially in legal, financial, or medical matters. He represents the law, both literal and karmic — the principle that actions have consequences and justice will ultimately be served. His energy is powerful, imposing, and absolutely fair.", reversedMeaning: "The King of Spades reversed indicates a man who abuses his authority, a judge who is corrupt, or someone who uses intellectual power to dominate rather than to serve justice. He may be cold, cruel, or manipulative, using the letter of the law to violate its spirit. The reversed King can also represent a man who has made a terrible decision under pressure, or an authority figure whose judgment cannot be trusted. In a reading, this card reversed warns against trusting a person in power who has not earned your trust. It can also indicate that you are being too harsh in your own self-judgment.", color: "black" },
];

export function getRandomCards(count: number): PlayingCardDef[] {
  const shuffled = [...PLAYING_CARDS].sort(() => Math.random() - 0.5);
  return shuffled.slice(0, count);
}

export function getCardById(id: number): PlayingCardDef | undefined {
  return PLAYING_CARDS.find(c => c.id === id);
}

export function getCardsBySuit(suit: Suit): PlayingCardDef[] {
  return PLAYING_CARDS.filter(c => c.suit === suit);
}

export function getSuitFromName(name: string): Suit | undefined {
  if (name.endsWith("Hearts") || name.endsWith("hearts")) return "hearts";
  if (name.endsWith("Diamonds") || name.endsWith("diamonds")) return "diamonds";
  if (name.endsWith("Clubs") || name.endsWith("clubs")) return "clubs";
  if (name.endsWith("Spades") || name.endsWith("spades")) return "spades";
  return undefined;
}

export interface SpreadDef {
  id: string;
  name: string;
  description: string;
  bestFor: string;
  cardCount: number;
  positions: string[];
  layout: "single" | "line" | "cross" | "grid" | "horseshoe" | "year";
}

